#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <smmintrin.h>
#include <tmmintrin.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static inline __m128i aes128_key_expand(__m128i key, __m128i assist) {
    /* not needed, we'll do standard expansion */
    return key;
}

/* AES-128 key expansion */
static void expand128(const uint8_t *key, __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    __m128i t = rk[0];
    #define EXPAND(i, rcon) do { \
        __m128i a = _mm_aeskeygenassist_si128(t, rcon); \
        a = _mm_shuffle_epi32(a, 0xff); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, a); \
        rk[i] = t; \
    } while(0)
    EXPAND(1, 0x01); EXPAND(2, 0x02); EXPAND(3, 0x04); EXPAND(4, 0x08);
    EXPAND(5, 0x10); EXPAND(6, 0x20); EXPAND(7, 0x40); EXPAND(8, 0x80);
    EXPAND(9, 0x1b); EXPAND(10, 0x36);
}

/* Encrypt 8 blocks in parallel (CTR) */
static void ctr8(const __m128i rk[11], __m128i ctr, uint8_t *out, const uint8_t *in, size_t nblocks) {
    const __m128i one = _mm_set_epi32(0,0,0,1);
    size_t i = 0;
    for (; i + 8 <= nblocks; i += 8) {
        __m128i c0=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c1=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c2=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c3=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c4=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c5=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c6=ctr; ctr=_mm_add_epi32(ctr, one);
        __m128i c7=ctr; ctr=_mm_add_epi32(ctr, one);
        c0=_mm_xor_si128(c0, rk[0]); c1=_mm_xor_si128(c1, rk[0]);
        c2=_mm_xor_si128(c2, rk[0]); c3=_mm_xor_si128(c3, rk[0]);
        c4=_mm_xor_si128(c4, rk[0]); c5=_mm_xor_si128(c5, rk[0]);
        c6=_mm_xor_si128(c6, rk[0]); c7=_mm_xor_si128(c7, rk[0]);
        for (int r = 1; r < 10; r++) {
            c0=_mm_aesenc_si128(c0, rk[r]); c1=_mm_aesenc_si128(c1, rk[r]);
            c2=_mm_aesenc_si128(c2, rk[r]); c3=_mm_aesenc_si128(c3, rk[r]);
            c4=_mm_aesenc_si128(c4, rk[r]); c5=_mm_aesenc_si128(c5, rk[r]);
            c6=_mm_aesenc_si128(c6, rk[r]); c7=_mm_aesenc_si128(c7, rk[r]);
        }
        c0=_mm_aesenclast_si128(c0, rk[10]); c1=_mm_aesenclast_si128(c1, rk[10]);
        c2=_mm_aesenclast_si128(c2, rk[10]); c3=_mm_aesenclast_si128(c3, rk[10]);
        c4=_mm_aesenclast_si128(c4, rk[10]); c5=_mm_aesenclast_si128(c5, rk[10]);
        c6=_mm_aesenclast_si128(c6, rk[10]); c7=_mm_aesenclast_si128(c7, rk[10]);
        __m128i p0=_mm_loadu_si128((const __m128i*)(in + (i+0)*16));
        __m128i p1=_mm_loadu_si128((const __m128i*)(in + (i+1)*16));
        __m128i p2=_mm_loadu_si128((const __m128i*)(in + (i+2)*16));
        __m128i p3=_mm_loadu_si128((const __m128i*)(in + (i+3)*16));
        __m128i p4=_mm_loadu_si128((const __m128i*)(in + (i+4)*16));
        __m128i p5=_mm_loadu_si128((const __m128i*)(in + (i+5)*16));
        __m128i p6=_mm_loadu_si128((const __m128i*)(in + (i+6)*16));
        __m128i p7=_mm_loadu_si128((const __m128i*)(in + (i+7)*16));
        _mm_storeu_si128((__m128i*)(out+(i+0)*16), _mm_xor_si128(c0, p0));
        _mm_storeu_si128((__m128i*)(out+(i+1)*16), _mm_xor_si128(c1, p1));
        _mm_storeu_si128((__m128i*)(out+(i+2)*16), _mm_xor_si128(c2, p2));
        _mm_storeu_si128((__m128i*)(out+(i+3)*16), _mm_xor_si128(c3, p3));
        _mm_storeu_si128((__m128i*)(out+(i+4)*16), _mm_xor_si128(c4, p4));
        _mm_storeu_si128((__m128i*)(out+(i+5)*16), _mm_xor_si128(c5, p5));
        _mm_storeu_si128((__m128i*)(out+(i+6)*16), _mm_xor_si128(c6, p6));
        _mm_storeu_si128((__m128i*)(out+(i+7)*16), _mm_xor_si128(c7, p7));
    }
}

int main() {
    size_t n = 60000ull * 1024;
    uint8_t *in = aligned_alloc(64, n);
    uint8_t *out = aligned_alloc(64, n);
    memset(in, 1, n);
    uint8_t key[16] = {0};
    __m128i rk[11];
    expand128(key, rk);
    __m128i ctr = _mm_setzero_si128();
    size_t nblocks = n / 16;
    /* warmup */
    ctr8(rk, ctr, out, in, nblocks);
    for (int i = 0; i < 4; i++) {
        double t0 = now();
        ctr8(rk, ctr, out, in, nblocks);
        double t1 = now();
        printf("aesni ctr8 %.3f ms  %.1f MB/s\n", (t1-t0)*1e3, n/(t1-t0)/1e6);
    }
    return 0;
}
