#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static size_t N;
static uint8_t *src, *dst;

typedef struct { size_t start, end; } Range;
static void *copy_worker(void *arg) {
    Range *r = arg;
    memcpy(dst + r->start, src + r->start, r->end - r->start);
    return NULL;
}
static void *read_worker(void *arg) {
    Range *r = arg;
    volatile uint64_t acc = 0;
    uint64_t *p = (uint64_t*)(src + r->start);
    size_t n = (r->end - r->start) / 8;
    for (size_t i = 0; i < n; i += 8) {
        acc += p[i] + p[i+1] + p[i+2] + p[i+3] + p[i+4] + p[i+5] + p[i+6] + p[i+7];
    }
    /* prevent elimination */
    if (acc == 0xdeadbeef) printf("%llu\n", (unsigned long long)acc);
    return NULL;
}

static void bench(const char *name, void *(*fn)(void*), int threads) {
    pthread_t th[16];
    Range ranges[16];
    size_t chunk = N / threads;
    double t0 = now();
    for (int rep = 0; rep < 5; rep++) {
        for (int i = 0; i < threads; i++) {
            ranges[i].start = i * chunk;
            ranges[i].end = (i == threads-1) ? N : (i+1)*chunk;
            pthread_create(&th[i], NULL, fn, &ranges[i]);
        }
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
    }
    double dt = (now() - t0) / 5;
    double bytes = (fn == read_worker) ? N : 2.0 * N;
    printf("%s threads=%d  %.3f ms  %.1f GB/s\n", name, threads, dt*1e3, bytes/dt/1e9);
}

int main() {
    N = 60000ull * 1024;
    src = aligned_alloc(64, N);
    dst = aligned_alloc(64, N);
    FILE *f = fopen("/dev/urandom","rb"); fread(src,1,N,f); fclose(f);
    memset(dst, 0, N);
    for (int t = 1; t <= 8; t *= 2) {
        bench("copy", copy_worker, t);
        bench("read", read_worker, t);
    }
    bench("copy", copy_worker, 6);
    bench("read", read_worker, 6);
    return 0;
}
