static __m128i ghash_reduce(__m128i hi, __m128i lo) {
    /* Intel's reduction for reflected representation */
    __m128i t1, t2;
    const __m128i poly = _mm_setr_epi32(1, 0, 0, 0xc2000000);
    /* lo is low 128 of product, hi high 128 */
    t1 = _mm_clmulepi64_si128(lo, poly, 0x00);
    t2 = _mm_shuffle_epi32(lo, 0x4e); /* swap halves */
    t2 = _mm_xor_si128(t2, t1);
    t1 = _mm_clmulepi64_si128(t2, poly, 0x00); /* wait this is not the standard form */
    /* Use well-known algorithm from Intel paper:
       X3:X2:X1:X0 = product (X3 highest)
       A = X0 * 0xc2000000 (pclmul low)
       B = (X0 : X1) xor (A << 64)   i.e. xor A into high half
       C = B_low * 0xc2000000
       D = (X2:X3) xor (B >> 64) xor C
    */
    return _mm_setzero_si128();
}

/* Correct reduction per Intel GCM whitepaper, reflected bits. */
static __m128i reduce_intel(__m128i X0_X1, __m128i X2_X3) {
    /* X0_X1 = low 128 (X0 in low 64, X1 in high 64)
       X2_X3 = high 128 (X2 low, X3 high) */
    const __m128i poly = _mm_set_epi32(0xc2000000, 0, 0, 1); /* this layout? */
    /* We'll instead implement bit-by-bit reduction in scalar for correctness first,
