static void xor_block(uint8_t *a, const uint8_t *b) {
    for (int i = 0; i < 16; i++) a[i] ^= b[i];
}
static void shift_right(uint8_t *v) { /* shift the 128-bit big-endian block right by 1 */
    int carry = 0;
    for (int i = 0; i < 16; i++) {
        int nc = v[i] & 1;
        v[i] = (v[i] >> 1) | (carry ? 0x80 : 0);
        carry = nc;
    }
