        J0[15] = 1;
    } else {
        /* not needed */
    }
    uint8_t counter[16]; memcpy(counter, J0, 16);
    /* increment counter */
    for (int i = 15; i >= 12; i--) { if (++counter[i]) break; }
    uint8_t stream[16];
    size_t off = 0;
    while (off < len) {
        aes_encrypt_block(rk, counter, stream);
        size_t m = len - off; if (m > 16) m = 16;
        for (size_t i = 0; i < m; i++) ct[off+i] = pt[off+i] ^ stream[i];
        off += m;
        for (int i = 15; i >= 12; i--) { if (++counter[i]) break; }
    }
    /* GHASH */
    uint8_t y[16] = {0};
    /* aad */
    size_t aoff = 0;
