    r = reduce(clmul_lo, clmul_hi);
    r = bswap16(r);
    _mm_storeu_si128((__m128i*)out, r);
    printf("bswap   "); for(int i=0;i<16;i++) printf("%02x", out[i]); printf(" %s\n", memcmp(out,expect,16)==0?"OK":"");

    /* variant 3: brev8 only */
    a = brev8(xv); b = brev8(hv);
    clmul(a, b);
    r = reduce(clmul_lo, clmul_hi);
    r = brev8(r);
    _mm_storeu_si128((__m128i*)out, r);
    printf("brev8   "); for(int i=0;i<16;i++) printf("%02x", out[i]); printf(" %s\n", memcmp(out,expect,16)==0?"OK":"");
    return 0;
}
