static __m128i brev8(__m128i x){
    const __m128i lut = _mm_setr_epi8(0,8,4,12,2,10,6,14,1,9,5,13,3,11,7,15);
    __m128i lo = _mm_and_si128(x, _mm_set1_epi8(0x0f));
