static void ghash_mul_scalar(uint8_t x[16], const uint8_t h[16]){
    uint8_t z[16]={0}, v[16]; memcpy(v,h,16);
    for(int i=0;i<16;i++) for(int bit=7;bit>=0;bit--){
        if((x[i]>>bit)&1) for(int k=0;k<16;k++) z[k]^=v[k];
        int lsb=v[15]&1, carry=0;
        for(int k=0;k<16;k++){ int nc=v[k]&1; v[k]=(v[k]>>1)|(carry?0x80:0); carry=nc; }
        if(lsb) v[0]^=0xe1;
    }
