static void product(__m128i a, __m128i b, __m128i *lo, __m128i *hi){
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    *lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    *hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
}
/* Intel reflected reduction: input product in lo (low 128), hi (high 128),
   bit 0 = x^0 of the reflected field. */
static __m128i reduce_intel(__m128i lo, __m128i hi){
    __m128i t1 = _mm_srli_epi64(lo, 63);
    __m128i t2 = _mm_srli_epi64(lo, 62);
    __m128i t3 = _mm_srli_epi64(lo, 57);
    __m128i t = _mm_xor_si128(_mm_xor_si128(t1, t2), t3);
    __m128i t_hi = _mm_slli_si128(t, 8);
    __m128i t_lo = _mm_srli_si128(t, 8);
    lo = _mm_xor_si128(lo, t_hi);
    hi = _mm_xor_si128(hi, t_lo);
