    __m128i hv = _mm_loadu_si128((const __m128i*)h);
    show("raw", gfmul(xv, hv));
    show("bswap in/out", bswap16(gfmul(bswap16(xv), bswap16(hv))));
    show("brev in/out", brev8(gfmul(brev8(xv), brev8(hv))));
