static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

/* single-thread baseline via EVP */
static void evp_enc(const uint8_t *key, const uint8_t *nonce, const uint8_t *pt, uint8_t *ct, size_t n, uint8_t tag[16]){
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen, tmplen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct+outlen, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
}

/* parallel: split plaintext into T chunks, encrypt each with its counter range
   using EVP by crafting per-chunk nonce? Can't, GCM counter is derived from nonce.
   Instead use AES_encrypt in CTR manually in threads, then one GHASH pass.
   First measure parallel CTR throughput with AES_encrypt (portable) — likely slow.
   Use aesni_ctr32_encrypt_blocks. */
void aesni_ctr32_encrypt_blocks(const uint8_t *in, uint8_t *out, size_t blocks,
                                const AES_KEY *key, const uint8_t ivec[16]);

typedef struct {
    const uint8_t *in; uint8_t *out; size_t blocks; const AES_KEY *key; uint8_t ivec[16];
} Job;
static void *ctr_worker(void *arg){
    Job *j = arg;
    aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->ivec);
    return NULL;
}

int main(){
    size_t n = 60000ull*1024;
    uint8_t *pt = aligned_alloc(64, n);
    uint8_t *ct = aligned_alloc(64, n);
    uint8_t *ct2 = aligned_alloc(64, n);
    FILE *f = fopen("/dev/urandom","rb"); fread(pt,1,n,f); fclose(f);
    uint8_t key[16], nonce[12];
    for(int i=0;i<16;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i+1;
    uint8_t tag[16];

    double t0 = now();
    evp_enc(key, nonce, pt, ct, n, tag);
    double t1 = now();
    printf("evp %.2f ms\n", (t1-t0)*1e3);

    AES_KEY aeskey;
    AES_set_encrypt_key(key, 128, &aeskey);
    /* counter block: nonce || 0x00000002 (GCM starts at 2 for data) */
    uint8_t ivec[16] = {0};
    memcpy(ivec, nonce, 12);
    ivec[15] = 2;

    int T = 4;
    size_t blocks = n/16;
    size_t per = blocks / T;
    pthread_t th[8]; Job jobs[8];
    t0 = now();
    for (int i = 0; i < T; i++) {
        jobs[i].in = pt + i*per*16;
        jobs[i].out = ct2 + i*per*16;
        jobs[i].blocks = (i==T-1) ? (blocks - i*per) : per;
        jobs[i].key = &aeskey;
        memcpy(jobs[i].ivec, ivec, 16);
        /* add i*per to the 32-bit counter (big-endian, last 4 bytes) */
        uint32_t ctr = ((uint32_t)ivec[12]<<24)|((uint32_t)ivec[13]<<16)|((uint32_t)ivec[14]<<8)|ivec[15];
        ctr += (uint32_t)(i*per);
        jobs[i].ivec[12]=ctr>>24; jobs[i].ivec[13]=ctr>>16; jobs[i].ivec[14]=ctr>>8; jobs[i].ivec[15]=ctr;
        pthread_create(&th[i], NULL, ctr_worker, &jobs[i]);
    }
    for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
    t1 = now();
    printf("parallel ctr %d threads %.2f ms  match %d\n", T, (t1-t0)*1e3, memcmp(ct, ct2, n)==0);

    /* single thread ctr for reference */
    t0 = now();
    aesni_ctr32_encrypt_blocks(pt, ct2, blocks, &aeskey, ivec);
    t1 = now();
    printf("single ctr %.2f ms match %d\n", (t1-t0)*1e3, memcmp(ct, ct2, n)==0);
    return 0;
}
